import React, { useState } from 'react';
import './ChallengeDay.css';

function ChallengeDay({ challenge }) {
  const [isCompleted, setIsCompleted] = useState(false);

  const handleComplete = () => {
    setIsCompleted(!isCompleted);
  };

  return (
    <div className={`challenge-card ${isCompleted ? 'completed' : ''}`}>
      <div className="challenge-header">
        <h3>{challenge.title}</h3>
        <span className={`difficulty ${challenge.difficulty}`}>
          {challenge.difficulty}
        </span>
      </div>
      <p className="challenge-description">{challenge.description}</p>
      <p className="challenge-date">{challenge.date}</p>
      <button
        className={`complete-btn ${isCompleted ? 'completed' : ''}`}
        onClick={handleComplete}
      >
        {isCompleted ? '✓ Completed' : 'Mark as Complete'}
      </button>
    </div>
  );
}

export default ChallengeDay;
